-- ----------------------------
-- View structure for ceshi
-- ----------------------------
DROP VIEW IF EXISTS `ceshi`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `ceshi` AS select `shjz`.`sys_menu`.`menu_id` AS `MENU_ID`,`shjz`.`sys_menu`.`menu_name` AS `MENU_NAME`,`shjz`.`sys_user`.`user_id` AS `USER_ID`,`shjz`.`sys_user`.`dept_id` AS `DEPT_ID` from (`shjz`.`sys_menu` join `shjz`.`sys_user`);

SET FOREIGN_KEY_CHECKS = 1;
